using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ApplyCircularDressing {
 const string A="Assets/Afrer_Seconds/",E=A+"05.Model/Environment/Common/",P=A+"05.Model/Props/Common/";
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string Src=>Repo+"/SourceAssets/CircularDressing/";static string Out=>Repo+"/Docs/검수/2026-11-06_CircularDressing/";
 static Color C(string hex){Color c;ColorUtility.TryParseHtmlString(hex,out c);return c;}
 static Material Mat(string kind,int variant=0){string key=kind=="Coat"?kind+variant:kind;string path=E+"Materials/CFD_"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}
  m.SetColor("_BaseColor",C(kind=="Coat"?"#A8B9C0":kind=="Steel"?"#6C7A83":kind=="Lamp"?"#BED8EA":"#202A30"));m.SetFloat("_Metallic",kind=="Steel"?.9f:.06f);m.SetFloat("_Smoothness",kind=="Steel"?.48f:.30f);
  string tex=kind=="Coat"?"Coat"+variant:kind;var baseTex=AssetDatabase.LoadAssetAtPath<Texture>(E+"Textures/CFD_"+tex+"_Base.png");if(baseTex){m.SetTexture("_BaseMap",baseTex);m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture>(E+"Textures/CFD_"+tex+"_MetallicSmoothness.png"));m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Smoothness",1);m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture>(E+"Textures/CFD_Micro_Normal.png"));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.16f);}
  if(kind=="Lamp"){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",C("#A7C3D6")*.35f);}EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;
 }
 static void Remap(GameObject g,int variant=0){foreach(var r in g.GetComponentsInChildren<Renderer>(true))r.sharedMaterials=r.sharedMaterials.Select(m=>m&&m.name.StartsWith("CFD_")&&new[]{"Coat","Steel","Dark","Lamp"}.Contains(m.name.Substring(4).Split('.')[0])?Mat(m.name.Substring(4).Split('.')[0],variant):m).ToArray();}
 static void Ready(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");Directory.CreateDirectory(Out);}
 public static object ImportEnvironment(){Ready();var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;
  try{AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string guid in AssetDatabase.FindAssets("CFD_ t:Texture2D",new[]{E+"Textures"})){string path=AssetDatabase.GUIDToAssetPath(guid);var t=AssetImporter.GetAtPath(path) as TextureImporter;t.sRGBTexture=!path.Contains("MetallicSmoothness")&&!path.Contains("Normal");if(path.Contains("Normal"))t.textureType=TextureImporterType.NormalMap;t.maxTextureSize=1024;t.SaveAndReimport();}
  var man=JObject.Parse(File.ReadAllText(Src+"environment_manifest.json"));foreach(var kv in man){string path=E+kv.Key+".fbx";var imp=AssetImporter.GetAtPath(path) as ModelImporter;imp.importAnimation=false;imp.importCameras=false;imp.importLights=false;imp.isReadable=true;imp.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);var g=(GameObject)PrefabUtility.InstantiatePrefab(model);g.name=kv.Key;Remap(g);foreach(var f in g.GetComponentsInChildren<MeshFilter>()){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;}PrefabUtility.SaveAsPrefabAsset(g,E+kv.Key+".prefab");UnityEngine.Object.DestroyImmediate(g);}
  }finally{Application.logMessageReceived-=cb;}File.WriteAllText(Out+"environment_import.json",JsonConvert.SerializeObject(logs,Formatting.Indented));return new{logs};
 }
 static GameObject Inst(string name,Transform parent){var a=AssetDatabase.LoadAssetAtPath<GameObject>((name=="CFD_TransferCabinet"||name=="CFD_LinenHamper"||name=="CFD_EmergencyCabinet"?P:E)+name+".prefab");return a?(GameObject)PrefabUtility.InstantiatePrefab(a,parent):null;}
 public static object CleanupImport(){foreach(var g in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.name=="CFD_LinenHamper"||g.name=="CFD_EmergencyCabinet"||g.name=="CFD_TransferCabinet"))UnityEngine.Object.DestroyImmediate(g);EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return true;}
 public static object ImportProps(){Ready();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;
  try{foreach(var name in new[]{"CFD_TransferCabinet","CFD_LinenHamper","CFD_EmergencyCabinet"}){
   var materials=new Dictionary<string,Material>();if(name!="CFD_TransferCabinet")foreach(var mi in JObject.Parse(File.ReadAllText(Src+name.Substring(4)+"_manifest.json"))["materials"]){string key=(string)mi["name"];var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));string path=P+"Materials/"+key+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){UnityEngine.Object.DestroyImmediate(mat);mat=old;}else AssetDatabase.CreateAsset(mat,path);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Smoothness",1);
    foreach(var map in new[]{new[]{"Albedo","_BaseMap"},new[]{"MetallicSmoothness","_MetallicGlossMap"},new[]{"Normal","_BumpMap"}}){string file=(string)mi[map[0]];if(string.IsNullOrEmpty(file))continue;string tp=P+"Textures/"+file;var imp=AssetImporter.GetAtPath(tp) as TextureImporter;imp.sRGBTexture=map[0]=="Albedo";if(map[0]=="Normal")imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();mat.SetTexture(map[1],AssetDatabase.LoadAssetAtPath<Texture>(tp));}
    mat.EnableKeyword("_METALLICSPECGLOSSMAP");mat.EnableKeyword("_NORMALMAP");mat.SetFloat("_BumpScale",.65f);EditorUtility.SetDirty(mat);materials[key]=mat;
   }
   string fbx=P+name+".fbx";var importer=AssetImporter.GetAtPath(fbx) as ModelImporter;importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.isReadable=true;importer.SaveAndReimport();var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(fbx));g.name=name;Remap(g);
   foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>m&&materials.ContainsKey(m.name)?materials[m.name]:m).ToArray();
   var renders=g.GetComponentsInChildren<Renderer>();var lod0=renders.Where(r=>!r.name.Contains("_LOD")||r.name.EndsWith("_LOD0")).ToArray();var b=lod0[0].bounds;foreach(var r in lod0.Skip(1))b.Encapsulate(r.bounds);var col=g.AddComponent<BoxCollider>();col.center=g.transform.InverseTransformPoint(b.center);col.size=b.size;
   if(name!="CFD_TransferCabinet"){var lod=g.GetComponent<LODGroup>()??g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.22f,renders.Where(r=>r.name.EndsWith("_LOD0")).ToArray()),new LOD(.07f,renders.Where(r=>r.name.EndsWith("_LOD1")).ToArray()),new LOD(.012f,renders.Where(r=>r.name.EndsWith("_LOD2")).ToArray())});lod.RecalculateBounds();}
   PrefabUtility.SaveAsPrefabAsset(g,P+name+".prefab");UnityEngine.Object.DestroyImmediate(g);
  }AssetDatabase.SaveAssets();}finally{Application.logMessageReceived-=cb;}File.WriteAllText(Out+"prop_import.json",JsonConvert.SerializeObject(logs,Formatting.Indented));return new{logs};
 }
 public static object Apply(){Ready();EditorSceneManager.OpenScene(A+"01.Scenes/Stage/Level_B5_Circular.unity");var scene=SceneManager.GetActiveScene();if(!File.Exists(Src+"B5_before.unity"))File.Copy(scene.path,Src+"B5_before.unity");var root=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular"));var group=root.transform.Find("B5_Art_C01_T01");if(!group){var gg=new GameObject("B5_Art_C01_T01");gg.transform.SetParent(root.transform,false);group=gg.transform;}
  var plan=JObject.Parse(File.ReadAllText(Src+"production_plan.json"));var done=new List<object>();var missing=new List<string>();
  foreach(var p in plan["placements"]){string id=(string)p["id"],model=(string)p["model"];var existing=group.Find(id+"_"+model);GameObject g=existing?existing.gameObject:Inst(model,group);if(!g){missing.Add(model);continue;}g.name=id+"_"+model;g.transform.localPosition=new Vector3((float)p["x"],(float)p["y"],-(float)p["v"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);g.transform.localScale=Vector3.one;Remap(g,(int)p["variant"]);foreach(var r in g.GetComponentsInChildren<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);
   if(model=="CFD_SealedLight"&&!g.GetComponentInChildren<Light>()){var l=new GameObject("TaskLight");l.transform.SetParent(g.transform,false);l.transform.localPosition=new Vector3(0,-.14f,0);var light=l.AddComponent<Light>();light.type=LightType.Point;light.color=C("#C1D5E4");light.intensity=.92f;light.range=5;light.shadows=LightShadows.None;}
   var rs=g.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);done.Add(new{id,code=(string)p["code"],model,position=new[]{g.transform.position.x,g.transform.position.y,g.transform.position.z},dimensions=new[]{b.size.x,b.size.y,b.size.z}});
  }
  foreach(var l in root.GetComponentsInChildren<Light>())if(l.name.StartsWith("B5-T01_"))l.enabled=false;
  Physics.SyncTransforms();EditorSceneManager.SaveScene(scene);File.WriteAllText(Out+"placements.json",JsonConvert.SerializeObject(done,Formatting.Indented));return new{placed=done.Count,missing=missing.Distinct().ToArray()};
 }
 public static object Capture(){Ready();var scene=SceneManager.GetActiveScene();var actors=scene.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToArray();var prior=actors.Select(r=>r.enabled).ToArray();foreach(var r in actors)r.enabled=false;
  var shots=new[]{new{name="B5_Tunnel_Detail",p=new Vector3(-16.9f,-80.35f,-1.1f),t=new Vector3(-21,-80.4f,14)},new{name="B5_LivingWall",p=new Vector3(-20.1f,-80.35f,-11.7f),t=new Vector3(-23,-81,-12)},new{name="B5_Entry_Dressing",p=new Vector3(-9.2f,-80.35f,-10),t=new Vector3(-21,-80.7f,-14)}};
  try{foreach(var s in shots){var go=new GameObject("ReviewCamera");var cam=go.AddComponent<Camera>();cam.transform.position=s.p;cam.transform.LookAt(s.t);cam.fieldOfView=70;cam.nearClipPlane=.04f;cam.farClipPlane=250;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=C("#0C1118");cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24);cam.targetTexture=rt;cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(Out+s.name+".png",tex.EncodeToPNG());RenderTexture.active=prev;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
  finally{for(int i=0;i<actors.Length;i++)actors[i].enabled=prior[i];EditorSceneManager.OpenScene(scene.path);}return new{shots=shots.Length};
 }
}
